create table if not exists public.bak_sale_price_triage_v1 (
  event_id uuid not null, run_id text not null, final_price numeric, current_price numeric, source_suspect text[],
  source_suspect_reason text, source_suspect_run_id text, source_suspect_at timestamptz, backed_up_at timestamptz default now(),
  primary key (event_id, run_id));
alter table public.bak_sale_price_triage_v1 enable row level security;

create or replace function public.apply_sale_price_triage_v1(p_run text, p_stage_run text default 'sale_outcome_sweep_v1_20261024', p_limit int default 500)
returns jsonb language plpgsql set search_path = public as $$
declare n_flag int; n_fill int;
begin
  create temp table _c on commit drop as
  select e.id, e.final_price, e.current_price, e.source_suspect, e.source_suspect_reason, e.source_suspect_run_id, e.source_suspect_at,
         s.amount, s.source_url url, s.snapshot_fetched_at, s.platform, s.basis, s.quote, b.bucket
  from sale_price_triage_bucket_v1 b
  join sale_outcome_sweep_stage_v1 s on s.event_id = b.event_id and s.run_id = p_stage_run
  join vehicle_events e on e.id = b.event_id
  join vehicles v on v.id = e.vehicle_id  -- events whose vehicle row is missing are left alone
  where s.kind = 'sold' and s.amount > 0 and e.final_price is distinct from s.amount
    and ((b.bucket = 'no_stored_price' and e.final_price is null) or (b.bucket <> 'no_stored_price' and e.final_price is not null and not exists (select 1 from price_basis_observation o where o.tbl = 'vehicle_events' and o.event_id = e.id and o.rule = 'sale_price_triage_v1' and o.superseded_at is null)))
  order by (b.bucket = 'no_stored_price'), b.event_id limit p_limit;
  insert into bak_sale_price_triage_v1 (event_id, run_id, final_price, current_price, source_suspect, source_suspect_reason, source_suspect_run_id, source_suspect_at)
  select id, p_run, final_price, current_price, source_suspect, source_suspect_reason, source_suspect_run_id, source_suspect_at from _c
  on conflict do nothing;
  insert into price_basis_observation (tbl, event_id, kind, stored_price, observed_status, observed_price, observed_on, source_url, evidence, rule, run_id)
  select 'vehicle_events', id, 'observed_page_status', coalesce(final_price, 0), 'sold', amount, snapshot_fetched_at::date, url,
         platform || ' ' || basis || ' says ' || quote || case when final_price is null then '; no stored price, filled from page'
           else '; stored final_price ' || final_price || ' kept; cause: ' || bucket || '; final_price flagged suspect' end,
         case when final_price is null then 'sale_price_page_fill_v1' else 'sale_price_triage_v1' end, p_run
  from _c on conflict (tbl, event_id, rule) do nothing;
  update vehicle_events e set source_suspect = array(select distinct x from unnest(coalesce(e.source_suspect,'{}') || array['final_price']) x),
         source_suspect_reason = 'page sold amount differs from stored final_price (' || c.bucket || ')', source_suspect_run_id = p_run, source_suspect_at = now()
  from _c c where c.id = e.id and c.final_price is not null and not ('final_price' = any(coalesce(e.source_suspect,'{}')));
  get diagnostics n_flag = row_count;
  update vehicle_events e set final_price = c.amount, current_price = coalesce(e.current_price, c.amount), updated_at = now()
  from _c c where c.id = e.id and c.final_price is null and e.final_price is null;
  get diagnostics n_fill = row_count;
  return jsonb_build_object('flagged', n_flag, 'filled', n_fill, 'candidates', (select count(*) from _c));
end $$;

create or replace function public.revert_sale_price_triage_v1(p_run text) returns jsonb language plpgsql set search_path = public as $$
declare n int;
begin
  update vehicle_events e set final_price = b.final_price, current_price = b.current_price, source_suspect = b.source_suspect,
         source_suspect_reason = b.source_suspect_reason, source_suspect_run_id = b.source_suspect_run_id, source_suspect_at = b.source_suspect_at
  from bak_sale_price_triage_v1 b where b.event_id = e.id and b.run_id = p_run;
  get diagnostics n = row_count;
  update price_basis_observation set superseded_at = now() where run_id = p_run and rule in ('sale_price_triage_v1','sale_price_page_fill_v1') and superseded_at is null;
  return jsonb_build_object('restored', n);
end $$;
revoke all on function public.apply_sale_price_triage_v1(text,text,int), public.revert_sale_price_triage_v1(text) from public, anon, authenticated;
